package com.aoo.bcg.gamespi.fsm;
import java.util.Map;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class CompositeStateValidatorTest{@Test void validatesCrossDimensionConstraints(){var validator=new CompositeStateValidator();var valid=new CompositeGameState(RoomLifecycleState.PLAYING,RoundLifecycleState.OPERATING,Map.of(0,PlayerLifecycleState.PLAYING),OperationWindowLifecycleState.OPEN,DissolveLifecycleState.NONE);assertTrue(validator.violations(valid).isEmpty());var invalid=new CompositeGameState(RoomLifecycleState.DISSOLVED,RoundLifecycleState.OPERATING,Map.of(0,PlayerLifecycleState.PLAYING),OperationWindowLifecycleState.OPEN,DissolveLifecycleState.VOTING);assertTrue(validator.violations(invalid).size()>=4);assertThrows(IllegalStateException.class,()->validator.requireValid(invalid));}}
